  "status": "SUPPORTED",
  "claim": {
    "component_id": "C007.component",
    "value": "Reliable interpretation of record dates is assumed only provisionally.",
    "scope": "Dates used in the reconstruction, without an assertion that they are reliable.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P005 explicitly presents reliable date interpretation as a provisional assumption."
    }
  },
  "signal_basis": {
    "component_id": "C007.signal_basis",
    "value": "The operation distinguishes event dates, record-creation dates and attachment dates, and examines whether linked approval records demonstrate approval before placement. Date interpretation remains provisional, with unreliable timestamps recognized as a limitation.",
    "scope": "Proposed documentary timing observations used in reconstruction; observing them does not independently establish timestamp reliability.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
