        },
        {
          "source_id": "P018",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle supplies the date distinctions, timing observation, provisional assumption and timestamp limitation; P018 identifies the observations as proposed."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C007.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to license this explicitly provisional methodological assumption."
    }
  },
  "rationale": "The claim accurately states the mapping's provisional treatment of date reliability. It makes no empirical assertion that the dates are reliable, so the operation need not establish their reliability to license this bounded claim.",
  "uncertainty": "Actual date reliability remains unestablished; that uncertainty is preserved by the claim itself.",
  "anomalies": []
